/** Browser-side accounting validation; unknown values remain null and timestamps are never refreshed implicitly. */
export function billingNumber(value, label) {
    if (!value.trim())
        return null;
    const number = Number(value);
    if (!Number.isFinite(number) || number < 0)
        throw new Error(`${label} must be a non-negative finite number, or empty for unknown.`);
    return number;
}
export function billingTimestamp(value, label) {
    const text = value.trim();
    if (!text)
        return null;
    if (!Number.isFinite(Date.parse(text)))
        throw new Error(`${label} must be a valid timestamp, or empty for unknown.`);
    return text;
}
export function billingStable(value) {
    const normalize = (entry) => Array.isArray(entry) ? entry.map(normalize)
        : entry && typeof entry === 'object' ? Object.fromEntries(Object.keys(entry).sort().map(key => [key, normalize(entry[key])])) : entry;
    return JSON.stringify(normalize(value));
}
export function billingPatch(base, next) {
    const patch = {};
    for (const key of ['mode', 'accountKey', 'plan', 'observedAt', 'validUntil', 'windows', 'prices', 'routing', 'skills', 'stopAtSubscriptionLimit', 'subscriptionWindowIds']) {
        const before = key === 'stopAtSubscriptionLimit' ? base[key] ?? false : key === 'windows'
            ? (base.windows ?? []).map((window) => ({ ...window, scope: window.scope ?? (base.mode === 'subscription' ? 'subscription' : 'other') }))
            : base[key] ?? null;
        if (billingStable(before) !== billingStable(next[key]))
            patch[key] = next[key];
    }
    if (Object.hasOwn(patch, 'windows') && next.windows.length && !next.observedAt)
        throw new Error('Enter an observed-at timestamp when recording limit windows. Editing a plan or routing preference does not refresh quota observations.');
    if (Object.hasOwn(patch, 'windows') && next.windows.length)
        patch.observedAt = next.observedAt;
    return patch;
}
export function billingInput(raw, original) {
    const windows = raw.windows.map((window, index) => {
        const id = String(window.id ?? ''), label = String(window.label ?? ''), unit = String(window.unit ?? '');
        if (!id.trim() || !label.trim() || !unit.trim())
            throw new Error(`Window ${index + 1} needs a key, label, and unit.`);
        return { id, label, unit, scope: window.scope ?? (raw.mode === 'subscription' ? 'subscription' : 'other'),
            limit: billingNumber(window.limit ?? '', 'Window limit'), remaining: billingNumber(window.remaining ?? '', 'Window remaining'), used: billingNumber(window.used ?? '', 'Window used'), resetAt: billingTimestamp(window.resetAt ?? '', 'Window reset time') };
    });
    if (new Set(windows.map((window) => window.id)).size !== windows.length)
        throw new Error('Limit-window keys must be unique.');
    const input = billingNumber(raw.inputPerMillion, 'Input price'), output = billingNumber(raw.outputPerMillion, 'Output price');
    const currency = raw.currency.trim() ? raw.currency : null;
    const capabilities = original && raw.capabilities === billingRaw(original).capabilities
        ? [...(original.routing?.capabilities ?? [])]
        : [...new Set(String(raw.capabilities).split(/[,\n]/).map(value => value.trim()).filter(Boolean))];
    const costRank = billingNumber(raw.costRank, 'Cost rank'), qualityRank = billingNumber(raw.qualityRank, 'Quality rank');
    if (costRank === 0 || qualityRank === 0)
        throw new Error('Routing ranks must be positive finite numbers, or empty for unknown.');
    if (!raw.tier && (capabilities.length || costRank !== null || qualityRank !== null))
        throw new Error('Choose a routing tier, or clear the routing preferences.');
    return { mode: raw.mode, accountKey: raw.accountKey.trim() || null, plan: raw.plan.trim() ? raw.plan : null,
        observedAt: billingTimestamp(raw.observedAt, 'Observed at'), validUntil: billingTimestamp(raw.validUntil, 'Valid until'), windows,
        prices: currency || input !== null || output !== null ? { currency, inputPerMillion: input, outputPerMillion: output } : null,
        routing: raw.tier ? { tier: raw.tier, capabilities, costRank, qualityRank } : null,
        skills: raw.overrideSkills ? [...raw.skills] : null,
        stopAtSubscriptionLimit: Boolean(raw.stopAtSubscriptionLimit),
        subscriptionWindowIds: String(raw.subscriptionWindowIds ?? '').trim() ? [...new Set(String(raw.subscriptionWindowIds).split(/[,\s]+/).filter(Boolean))] : null };
}
export function billingRaw(record) {
    const text = (value) => value === null || value === undefined ? '' : String(value);
    return { mode: record.mode ?? 'unknown', plan: text(record.plan), accountKey: text(record.accountKey),
        stopAtSubscriptionLimit: Boolean(record.stopAtSubscriptionLimit), subscriptionWindowIds: (record.subscriptionWindowIds ?? []).join(', '),
        observedAt: text(record.observedAt), validUntil: text(record.validUntil), currency: text(record.prices?.currency),
        inputPerMillion: text(record.prices?.inputPerMillion), outputPerMillion: text(record.prices?.outputPerMillion),
        tier: record.routing?.tier ?? '', capabilities: (record.routing?.capabilities ?? []).join(', '),
        costRank: text(record.routing?.costRank), qualityRank: text(record.routing?.qualityRank),
        overrideSkills: Array.isArray(record.skills), skills: [...(record.skills ?? record.effectiveSkills ?? [])],
        windows: (record.windows ?? []).map((window) => ({ ...Object.fromEntries(['id', 'label', 'unit', 'limit', 'remaining', 'used', 'resetAt'].map(key => [key, text(window[key])])), scope: window.scope ?? (record.mode === 'subscription' ? 'subscription' : 'other') })) };
}
